-- ========================================================================

-- Computed interpretation grade for a DEXA bone-density result (four-axis engine).

CREATE TABLE dexa_bone_density_test_result_grade (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    dexa_bone_density_test_result_id UUID NOT NULL UNIQUE
        REFERENCES dexa_bone_density_test_result(id) ON DELETE CASCADE,

    -- Axis A: result classification
    result_classification VARCHAR(15) NOT NULL DEFAULT ''
        CHECK (result_classification IN ('normal', 'abnormal', 'critical', 'inconclusive', '')),

    -- Axis B: severity and structured reporting (reporting_category carries the WHO classification)
    abnormality_severity VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (abnormality_severity IN ('none', 'minor', 'moderate', 'major', '')),
    reporting_category VARCHAR(50) NOT NULL DEFAULT '',

    -- Axis C: report completeness
    report_completeness_percent INTEGER
        CHECK (report_completeness_percent IS NULL OR report_completeness_percent BETWEEN 0 AND 100),

    -- Axis D: follow-up urgency
    follow_up_urgency VARCHAR(15) NOT NULL DEFAULT ''
        CHECK (follow_up_urgency IN ('routine', 'recommended', 'urgent', 'critical-alert', '')),
    target_timeframe VARCHAR(50) NOT NULL DEFAULT '',
    recommended_action VARCHAR(500) NOT NULL DEFAULT '',

    recommendation VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (recommendation IN ('no-action', 'routine-follow-up', 'further-imaging', 'specialist-referral', 'urgent-review', '')),
    clinician_notes TEXT NOT NULL DEFAULT '',
    signed_at TIMESTAMPTZ,
    graded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TRIGGER trigger_dexa_bone_density_test_result_grade_updated_at
    BEFORE UPDATE ON dexa_bone_density_test_result_grade
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE dexa_bone_density_test_result_grade IS
    'Computed four-axis interpretation grade: result classification, abnormality severity / structured-reporting category (WHO densitometric classification), report completeness, and follow-up urgency. Severe osteoporosis or an identified vertebral fracture auto-escalates the follow-up urgency to urgent / critical-alert regardless of the other axes.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.dexa_bone_density_test_result_id IS
    'Foreign key to the parent result (unique, 1:1).';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.result_classification IS
    'Axis A overall classification: normal, abnormal, critical, inconclusive.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.abnormality_severity IS
    'Axis B abnormality severity: none, minor, moderate, major.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.reporting_category IS
    'Axis B structured-reporting category label, carrying the WHO densitometric classification (normal / osteopenia / osteoporosis / severe-osteoporosis).';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.report_completeness_percent IS
    'Axis C report completeness as a percentage of mandatory report sections (0-100).';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.follow_up_urgency IS
    'Axis D follow-up urgency: routine, recommended, urgent, critical-alert.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.target_timeframe IS
    'Target timeframe for the recommended follow-up implied by the urgency.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.recommended_action IS
    'Axis D concise recommended action derived from the urgency.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.recommendation IS
    'Overall recommendation: no-action, routine-follow-up, further-imaging, specialist-referral, urgent-review.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.clinician_notes IS
    'Free-text interpretation / sign-off notes.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.signed_at IS
    'Timestamp of the reporting clinician electronic signature.';
COMMENT ON COLUMN dexa_bone_density_test_result_grade.graded_at IS
    'Timestamp when the engine last computed the result.';

