-- Safety-critical flags for a DEXA bone-density result, independent of the axes.

CREATE TABLE dexa_bone_density_test_result_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    dexa_bone_density_test_result_grade_id UUID NOT NULL
        REFERENCES dexa_bone_density_test_result_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(40) NOT NULL DEFAULT ''
        CHECK (category IN (
            'critical-result-alert',
            'incidental-finding',
            'discrepancy-with-request',
            'abnormal-requiring-action',
            'urgent-referral',
            'inadequate-technique',
            'unexpected-finding',
            'missing-impression',
            'missing-measurement',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_dexa_bone_density_test_result_grade_flag_grade_id
    ON dexa_bone_density_test_result_grade_flag(dexa_bone_density_test_result_grade_id);

CREATE TRIGGER trigger_dexa_bone_density_test_result_grade_flag_updated_at
    BEFORE UPDATE ON dexa_bone_density_test_result_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

